export const ECLIPSE_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/eclipse-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getEclipseStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(ECLIPSE_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
